"""Ordered notification log, stored inside the depot state dict so that
snapshots (undo, failed operations, save/load) cover it automatically."""


def emit(state, *event):
    state["notes"].append(list(event))


def notifications(state):
    return [tuple(n) for n in state["notes"]]
