"""Money helpers. All amounts are integer cents."""
import os
import sys
import tomllib
from decimal import Decimal

_HERE = os.path.dirname(os.path.abspath(__file__))
if _HERE not in sys.path:
    sys.path.insert(0, _HERE)

from vendor.rounding import round_cents  # noqa: E402  (read-only vendor helper)


def load_data(path=None):
    path = path or os.path.join(_HERE, "data.toml")
    with open(path, "rb") as f:
        return tomllib.load(f)


def list_price(unit_cost, markup, mode):
    """unit_cost * (1 + markup), rounded to a whole cent using `mode`."""
    value = Decimal(unit_cost) * (1 + Decimal(str(markup)))
    return round_cents(value, mode)


def sale_amount(price, qty, bulk_threshold, bulk_discount_pct, mode):
    """price * qty, with bulk discount when qty >= bulk_threshold."""
    amount = Decimal(price) * qty
    if qty >= bulk_threshold:
        amount = amount * (100 - Decimal(str(bulk_discount_pct))) / 100
    return round_cents(amount, mode)


def turnover(units_shipped, average_held):
    """units shipped / average units held; None if the average is 0."""
    if not average_held:
        return None
    return units_shipped / average_held
