"""Supplier reliability and orders. Operates on the depot state dict."""
from events import emit

START = 3
LOW, HIGH = 0, 5
SUSPEND_AT = 1


class SupplierError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


def _sup(state, name):
    s = state["sup"].get(name)
    if s is None:
        raise SupplierError("UNKNOWN_SUPPLIER")
    return s


def reliability(state, name):
    return _sup(state, name)["rel"]


def place_order(state, supplier, sku, qty, due_day):
    if not isinstance(supplier, str) or not supplier:
        raise SupplierError("INVALID_SUPPLIER")
    if isinstance(qty, bool) or not isinstance(qty, int) or qty <= 0:
        raise SupplierError("INVALID_QTY")
    if isinstance(due_day, bool) or not isinstance(due_day, int):
        raise SupplierError("INVALID_DUE_DAY")
    s = state["sup"].setdefault(supplier, {"rel": START, "announced": False})
    if s["rel"] <= SUSPEND_AT:
        raise SupplierError("SUPPLIER_SUSPENDED")
    oid = state["next_id"]
    state["next_id"] += 1
    state["orders"][str(oid)] = {"supplier": supplier, "sku": sku, "qty": qty,
                                 "due": due_day, "delivered": False}
    return oid


def deliver(state, order_id, day, unit_cost, late_penalty_pct):
    """Record a delivery. Returns the amount payable in cents, or None when the
    delivery is late and no late-penalty percentage has been configured."""
    o = state["orders"].get(str(order_id))
    if o is None:
        raise SupplierError("UNKNOWN_ORDER")
    if o["delivered"]:
        raise SupplierError("ALREADY_DELIVERED")
    o["delivered"] = True
    s = state["sup"][o["supplier"]]
    late = day > o["due"]
    s["rel"] = max(LOW, min(HIGH, s["rel"] + (-1 if late else 1)))
    if s["rel"] <= SUSPEND_AT and not s["announced"]:
        s["announced"] = True
        emit(state, "SUPPLIER_SUSPENDED", o["supplier"])
    full = unit_cost * o["qty"]
    if not late:
        return full
    if late_penalty_pct is None:
        return None
    from decimal import Decimal
    from money import round_cents
    return full  # placeholder replaced below by Depot (needs rounding mode)


def reinstate(state, name):
    s = _sup(state, name)
    s["rel"] = 2
    s["announced"] = False
