"""Depot: multi-warehouse inventory and cash ledger."""
import copy
import functools
import json
from decimal import Decimal

import events
import money
import suppliers
from money import round_cents


class DepotError(Exception):
    def __init__(self, code, *args):
        super().__init__(code, *args)
        self.code = code


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def mutating(blocking=False):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(self, *a, **kw):
            if self._depth:
                return fn(self, *a, **kw)
            snap = copy.deepcopy(self._s)
            self._depth += 1
            try:
                try:
                    result = fn(self, *a, **kw)
                    self._check_overdrawn()
                    self._touch()
                except suppliers.SupplierError as e:
                    raise DepotError(e.code) from None
            except BaseException:
                self._s = snap
                raise
            finally:
                self._depth -= 1
            if blocking:
                self._undo, self._blocked = None, True
            else:
                self._undo, self._blocked = snap, False
            return result
        return wrapper
    return deco


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode, *,
                 late_penalty_pct=None, restock_perishables_on_return=None,
                 data_path=None):
        self.warehouses = list(warehouses)
        for w in self.warehouses:
            if w not in capacities:
                raise ValueError("missing capacity for %s" % w)
        self.capacities = dict(capacities)
        self.mode = rounding_mode
        self.late_penalty_pct = late_penalty_pct
        self.restock_perishables = restock_perishables_on_return
        self.data = money.load_data(data_path)
        self._depth = 0
        self._undo = None
        self._blocked = False
        self._s = {
            "day": 0, "cash": opening_cash, "overdrawn": False,
            "items": {}, "lots": {w: {} for w in self.warehouses},
            "shipped": {}, "returned": {}, "ship_log": [], "held": {"0": 0},
            "fired": [], "notes": [], "sup": {}, "orders": {}, "next_id": 1,
        }

    # ---- read-only ----
    @property
    def cash(self):
        return self._s["cash"]

    @property
    def day(self):
        return self._s["day"]

    def reliability(self, supplier):
        try:
            return suppliers.reliability(self._s, supplier)
        except suppliers.SupplierError as e:
            raise DepotError(e.code) from None

    def notifications(self):
        return events.notifications(self._s)

    # ---- helpers ----
    def _item(self, sku):
        it = self._s["items"].get(sku)
        if it is None:
            raise DepotError("UNKNOWN_SKU")
        return it

    def _wh(self, wh):
        if wh not in self.capacities:
            raise DepotError("UNKNOWN_WAREHOUSE")

    def _qty(self, qty):
        if not _is_int(qty) or qty <= 0:
            raise DepotError("INVALID_QTY")

    def _lots(self, wh, sku):
        return self._s["lots"][wh].setdefault(sku, [])

    def _units(self, wh, sku):
        return sum(q for _, q in self._s["lots"][wh].get(sku, []))

    def _wh_total(self, wh):
        return sum(q for lots in self._s["lots"][wh].values() for _, q in lots)

    def _total(self):
        return sum(self._wh_total(w) for w in self.warehouses)

    def _touch(self):
        self._s["held"][str(self._s["day"])] = self._total()

    def _check_overdrawn(self):
        s = self._s
        if s["cash"] < 0:
            if not s["overdrawn"]:
                s["overdrawn"] = True
                events.emit(s, "OVERDRAWN")
        else:
            s["overdrawn"] = False

    def _refresh_arming(self, sku, wh):
        if self._units(wh, sku) > self._s["items"][sku]["reorder_level"]:
            pair = [sku, wh]
            if pair in self._s["fired"]:
                self._s["fired"].remove(pair)

    def _add_lot(self, wh, sku, day, qty):
        lots = self._lots(wh, sku)
        lots.append([day, qty])
        lots.sort(key=lambda l: l[0])  # stable: keeps FIFO within a day

    def _take(self, wh, sku, qty):
        """Consume oldest-first; returns list of [day, qty] taken."""
        lots = self._lots(wh, sku)
        taken, need = [], qty
        while need:
            d, q = lots[0]
            use = min(q, need)
            taken.append([d, use])
            need -= use
            if use == q:
                lots.pop(0)
            else:
                lots[0][1] = q - use
        return taken

    # ---- items ----
    @mutating()
    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        if sku in self._s["items"]:
            raise DepotError("DUPLICATE_SKU")
        if not _is_int(unit_cost) or unit_cost <= 0:
            raise DepotError("INVALID_COST")
        if not _is_int(reorder_level) or reorder_level < 0:
            raise DepotError("INVALID_REORDER_LEVEL")
        if shelf_life_days is not None and (
                not _is_int(shelf_life_days) or shelf_life_days < 1):
            raise DepotError("INVALID_SHELF_LIFE")
        self._s["items"][sku] = {"unit_cost": unit_cost,
                                 "reorder_level": reorder_level,
                                 "shelf_life_days": shelf_life_days}

    def list_price(self, sku):
        it = self._item(sku)
        return money.list_price(it["unit_cost"], self.data["markup"], self.mode)

    # ---- stock movement ----
    def _receive(self, sku, qty, wh):
        it = self._item(sku)
        self._wh(wh)
        self._qty(qty)
        if self._s["cash"] < 0:
            raise DepotError("OVERDRAWN")
        if self._wh_total(wh) + qty > self.capacities[wh]:
            raise DepotError("CAPACITY")
        cost = it["unit_cost"] * qty
        if self._s["cash"] - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        self._s["cash"] -= cost
        self._add_lot(wh, sku, self._s["day"], qty)
        self._refresh_arming(sku, wh)

    @mutating()
    def receive(self, sku, qty, wh):
        self._receive(sku, qty, wh)

    @mutating()
    def receive_bulk(self, receipts):
        for sku, qty, wh in receipts:
            self._receive(sku, qty, wh)

    @mutating()
    def ship(self, sku, qty, wh, price):
        it = self._item(sku)
        self._wh(wh)
        self._qty(qty)
        if not _is_int(price) or price < 0:
            raise DepotError("INVALID_PRICE")
        if self._units(wh, sku) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        self._take(wh, sku, qty)
        s = self._s
        s["cash"] += money.sale_amount(price, qty, self.data["bulk_threshold"],
                                       self.data["bulk_discount_pct"], self.mode)
        s["shipped"][sku] = s["shipped"].get(sku, 0) + qty
        s["ship_log"].append([s["day"], qty])
        left = self._units(wh, sku)
        if left <= it["reorder_level"]:
            if [sku, wh] not in s["fired"]:
                s["fired"].append([sku, wh])
                events.emit(s, "REORDER", sku, wh)
        else:
            self._refresh_arming(sku, wh)

    @mutating()
    def transfer(self, sku, qty, from_wh, to_wh):
        self._item(sku)
        self._wh(from_wh)
        self._wh(to_wh)
        self._qty(qty)
        if from_wh == to_wh:
            raise DepotError("SAME_WAREHOUSE")
        if self._units(from_wh, sku) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        if self._wh_total(to_wh) + qty > self.capacities[to_wh]:
            raise DepotError("CAPACITY")
        cost = self.data["transfer_credit_cents_per_unit"] * qty
        if self._s["cash"] - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        self._s["cash"] -= cost
        for d, q in self._take(from_wh, sku, qty):
            self._add_lot(to_wh, sku, d, q)
        self._refresh_arming(sku, from_wh)
        self._refresh_arming(sku, to_wh)

    @mutating()
    def return_goods(self, sku, qty, wh, price):
        it = self._item(sku)
        self._wh(wh)
        self._qty(qty)
        if not _is_int(price) or price < 0:
            raise DepotError("INVALID_PRICE")
        s = self._s
        if s["returned"].get(sku, 0) + qty > s["shipped"].get(sku, 0):
            raise DepotError("RETURN_EXCEEDS")
        perishable = it["shelf_life_days"] is not None
        restock = True
        if perishable:
            if self.restock_perishables is None:
                raise DepotError("RETURN_POLICY_UNDECIDED")
            restock = bool(self.restock_perishables)
        if restock and self._wh_total(wh) + qty > self.capacities[wh]:
            raise DepotError("CAPACITY")
        s["returned"][sku] = s["returned"].get(sku, 0) + qty
        s["cash"] -= price * qty
        if restock:
            self._add_lot(wh, sku, s["day"], qty)
            self._refresh_arming(sku, wh)

    # ---- queries ----
    def stock(self, sku, wh=None):
        self._item(sku)
        if wh is not None:
            self._wh(wh)
            return self._units(wh, sku)
        return sum(self._units(w, sku) for w in self.warehouses)

    def report(self):
        rows = []
        for sku in sorted(self._s["items"]):
            cost = self._s["items"][sku]["unit_cost"]
            for wh in sorted(self.warehouses):
                u = self._units(wh, sku)
                rows.append((sku, wh, u, u * cost))
        return rows

    def turnover(self, start_day, end_day):
        s = self._s
        shipped = sum(q for d, q in s["ship_log"] if start_day <= d <= end_day)
        days = range(start_day, end_day + 1)
        if not len(days):
            return None
        held = [s["held"].get(str(d), 0) for d in days]
        return money.turnover(shipped, Decimal(sum(held)) / len(held)
                              if sum(held) else 0)

    @mutating()
    def audit(self, counts):
        if not counts:
            raise DepotError("EMPTY_AUDIT")
        for sku, wh in counts:
            self._item(sku)
            self._wh(wh)
        for (sku, wh) in sorted(counts):
            ledger, counted = self._units(wh, sku), counts[(sku, wh)]
            if ledger != counted:
                events.emit(self._s, "AUDIT_MISMATCH", sku, wh, ledger, counted)

    # ---- time ----
    @mutating(blocking=True)
    def advance_day(self):
        s = self._s
        s["day"] += 1
        s["cash"] -= self.data["storage_cents_per_unit_day"] * self._total()
        for wh in self.warehouses:
            for sku in sorted(s["lots"][wh]):
                life = s["items"][sku]["shelf_life_days"]
                if life is None:
                    continue
                lots = s["lots"][wh][sku]
                gone = sum(q for d, q in lots if s["day"] - d > life)
                if gone:
                    s["lots"][wh][sku] = [l for l in lots
                                          if s["day"] - l[0] <= life]
                    events.emit(s, "EXPIRY", sku, wh, gone)
                    self._refresh_arming(sku, wh)
        # overdrawn check runs last, in the wrapper

    # ---- suppliers ----
    @mutating()
    def place_order(self, supplier, sku, qty, due_day):
        self._item(sku)
        return suppliers.place_order(self._s, supplier, sku, qty, due_day)

    @mutating()
    def deliver(self, order_id, day):
        o = self._s["orders"].get(str(order_id))
        cost = self._s["items"][o["sku"]]["unit_cost"] if o else 0
        pay = suppliers.deliver(self._s, order_id, day, cost,
                                self.late_penalty_pct)
        if pay is not None and day > o["due"]:
            full = cost * o["qty"]
            pay = round_cents(Decimal(full) * (100 - Decimal(str(
                self.late_penalty_pct))) / 100, self.mode)
        return pay

    @mutating()
    def reinstate(self, supplier):
        suppliers.reinstate(self._s, supplier)

    # ---- undo / persistence ----
    def undo(self):
        if self._blocked:
            raise DepotError("UNDO_BLOCKED")
        if self._undo is None:
            raise DepotError("NOTHING_TO_UNDO")
        self._s = self._undo
        self._undo = None

    def save(self):
        return json.dumps({"version": 1, "state": self._s}, sort_keys=True)

    def load(self, text):
        try:
            obj = json.loads(text)
            if not isinstance(obj, dict) or obj.get("version") != 1:
                raise ValueError
            st = obj["state"]
            keys = set(self._s)
            if not isinstance(st, dict) or set(st) != keys:
                raise ValueError
            if set(st["lots"]) != set(self.warehouses):
                raise ValueError
            if not _is_int(st["day"]) or not _is_int(st["cash"]):
                raise ValueError
            for k in ("items", "shipped", "returned", "held", "sup", "orders"):
                if not isinstance(st[k], dict):
                    raise ValueError
            for k in ("ship_log", "fired", "notes"):
                if not isinstance(st[k], list):
                    raise ValueError
            for wh, per in st["lots"].items():
                for sku, lots in per.items():
                    for lot in lots:
                        if len(lot) != 2 or not all(_is_int(x) for x in lot):
                            raise ValueError
        except (ValueError, KeyError, TypeError):
            raise DepotError("BAD_SAVE") from None
        snap = self._s
        self._s = st
        self._undo, self._blocked = snap, False
