"""Seeded demand simulation."""
import random

import money


def simulate(days, seed, data_path=None):
    demand = money.load_data(data_path)["demand"]
    rng = random.Random(seed)
    result = []
    for _ in range(days):
        orders = []
        for sku in sorted(demand):
            qty = rng.randint(demand[sku]["min"], demand[sku]["max"])
            if qty > 0:
                orders.append((sku, qty))
        result.append(orders)
    return result
